	p := Defaults()
	p.SecretsPath = filepath.Join(t.TempDir(), REDACTED, "secrets.json")
	p.DescriptorPath = filepath.Join(t.TempDir(), "descriptor.json")
	p.JVMOpts = "-Dmarker=" + REDACTED

	store := newTestStore(t, p.SecretsPath)
