		if err := WriteDescriptor(path, bad); err != nil {
			t.Fatalf("WriteDescriptor: %v", err)
		}
		after, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		if bytes.Equal(before, after) {
			t.Error("the second write did not replace the file")
		}
		if _, err := LoadDescriptor(path); err != nil {
			t.Errorf("the rewritten file is not a whole descriptor: %v", err)
		}
		assertOnlyEntries(t, dir, "descriptor.json")
	})
}

func TestDescriptorPath(t *testing.T) {
	t.Run("NEXUS_BENCH_DESCRIPTOR wins", func(t *testing.T) {
