		if err != nil {
			t.Fatal(err)
		}
		if first == nil {
			first = got
		} else if !bytes.Equal(first, got) {
			t.Errorf("write #%d (%s) differs from the first one:\n%s\n---\n%s", i+1, name, got, first)
